mapper.select:
/** com.khnp.pels.api.TstEventStrokeByPageList */
SELECT T1.EVENT_SNO,
       T2.LINE_PTH_DCR
  FROM GE_PL_EVNT01_M T1
       JOIN GE_PL_EVNT0101_D T2
            ON T1.EVENT_SNO = T2.EVENT_SNO
 WHERE T1.PWPL_ID = #{pwplId, jdbcType=BIGINT}
   AND T1.CHCK_SNO = #{chckSno, jdbcType=BIGINT}
   AND T1.PAGE_CNT = #{pageNo, jdbcType=INTEGER}
 ORDER
    BY T1.EVENT_CRTE_DT
     , T1.EVENT_SNO

SELECT CHCK_EVENT_SEQ.NEXTVAL
  FROM DUAL
CONNECT BY LEVEL <= #{value, jdbcType=INTEGER}

mapper.insert:
/** com.khnp.pels.api.TstEventBatchInsert */
INSERT
  INTO GE_PL_EVNT01_M
     ( EVENT_SNO
     , EVENT_TYP_SQNO
     , PWPL_ID
     , CHCK_SNO
     , PAGE_CNT
     , INSRTN_PAGE_CNT
     , PDF_PAGE_CNT
     , EVENT_DOC_SQNO
     , USER_ID
     , EVENT_CRTE_DT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{eventTyp, jdbcType=INTEGER}
     , #{pwplId, jdbcType=VARCHAR}
     , #{chckSno, jdbcType=BIGINT}
     , #{pageNo, jdbcType=INTEGER}
     , #{pageAddSeq, jdbcType=INTEGER}
     , #{pdfPageNo, jdbcType=INTEGER}
     , #{eventTrgtSeq, jdbcType=INTEGER}
     , #{userId, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{eventDt, jdbcType=VARCHAR},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
     )

/** com.khnp.pels.api.TstEventInsert */

    SELECT CHCK_EVENT_SEQ.NEXTVAL FROM DUAL

INSERT
  INTO GE_PL_EVNT01_M
     ( EVENT_SNO
     , EVENT_TYP_SQNO
     , PWPL_ID
     , CHCK_SNO
     , PAGE_CNT
     , INSRTN_PAGE_CNT
     , PDF_PAGE_CNT
     , EVENT_DOC_SQNO
     , USER_ID
     , EVENT_CRTE_DT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{eventTyp, jdbcType=INTEGER}
     , #{pwplId, jdbcType=VARCHAR}
     , #{chckSno, jdbcType=BIGINT}
     , #{pageNo, jdbcType=INTEGER}
     , #{pageAddSeq, jdbcType=INTEGER}
     , #{pdfPageNo, jdbcType=INTEGER}
     , #{eventTrgtSeq, jdbcType=INTEGER}
     , #{userId, jdbcType=VARCHAR}
     , TO_TIMESTAMP(#{eventDt, jdbcType=VARCHAR},'YYYY-MM-DD"T"HH24:MI:SS.FF3')
     )

/** com.khnp.pels.api.TstEventStrokeInsert */
INSERT
  INTO GE_PL_EVNT0101_D
     ( EVENT_SNO
     , X_CRDNT
     , Y_CRDNT
     , LINE_PTH_DCR
     , LINE_SNO
     , LINE_ETT
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{posX, jdbcType=INTEGER}
     , #{posY, jdbcType=INTEGER}
     , #{pointPath, jdbcType=BLOB}
     , #{strokeColor, jdbcType=INTEGER}
     , #{strokeWidth, jdbcType=NUMERIC}
     )

/** com.khnp.pels.api.TstEventImageInsert */
INSERT
  INTO GE_PL_EVNT0102_D
     ( EVENT_SNO
     , X_CRDNT
     , Y_CRDNT
     , WDTH_NUMV
     , HDTH_NUMV
     , URL_INFO
     )
VALUES
     ( #{eventSno, jdbcType=BIGINT}
     , #{posX, jdbcType=INTEGER}
     , #{posY, jdbcType=INTEGER}
     , #{width, jdbcType=INTEGER}
     , #{height, jdbcType=INTEGER}
     , #{fileUrl, jdbcType=VARCHAR}
     )
